let posterAspectErrors = 0;
for (let i = 0; i < cardGeometry.posters.length; i++) {
  const p = cardGeometry.posters[i];
  const diff = Math.abs(p.ratio - (16 / 9));
  if (diff > 0.002 || p.mediaWidth !== 352 || p.mediaHeight !== 198) {
    posterAspectErrors++;
  }
}
assert(posterAspectErrors === 0, `All ${cardGeometry.posters.length} Home poster cards strictly conform to 352x198 (16:9 aspect ratio, ratio=1.7778)`);

console.log(`  Evaluating ${cardGeometry.moviePosters.length} poster cards in 6-column Grid view...`);
